const BATCHES = 10;   // 批次数，每批处理 limit 条执行记录
const LIMIT = 500;    // 每批执行记录条数（避免 OOM）
const items = [];
for (let i = 0; i < BATCHES; i++) {
  items.push({ json: { batch: i, offset: i * LIMIT, limit: LIMIT, batches: BATCHES } });
}
return items;

const BATCH_SIZE = 300;
const WINDOW_MS = 30000;

const pgItems = $('查询n8n执行历史').all();
const sshItems = $('查询审计记录').all();

const auditRows = [];
for (const it of sshItems) {
  const raw = it.json || {};
  const stdout = String(raw.stdout || raw.data || '');
  const lines = stdout.split(/\r?\n/).filter(function (l) { return l.length > 0; });
  if (!lines.length) continue;
  const headers = lines[0].split('\t');
  for (let i = 1; i < lines.length; i++) {
    const vals = lines[i].split('\t');
    const row = {};
    for (let h = 0; h < headers.length; h++) row[headers[h]] = vals[h] != null ? vals[h] : '';
    auditRows.push(row);
  }
}

const byKey = new Map();
for (const a of auditRows) {
  const key = String(a.country || '').toLowerCase() + '\u0001' + String(a.action || '');
  if (!byKey.has(key)) byKey.set(key, []);
  byKey.get(key).push(a);
}

function toTs(s) { const t = Date.parse(String(s || '')); return isNaN(t) ? null : t; }
function sqlQuote(v) { return "'" + String(v).replace(/\\/g, '\\\\').replace(/'/g, "''") + "'"; }

const statements = [];
let matched = 0;
let unmatched = 0;
const seen = new Set();

for (const it of pgItems) {
  const n = it.json || {};
  const key = String(n.country || '').toLowerCase() + '\u0001' + String(n.action || '');
  const bucket = byKey.get(key);
  const nt = toTs(n.started);
  if (!bucket || nt == null || !n.token) { unmatched++; continue; }
  let best = null;
  let bestDiff = Infinity;
  for (const a of bucket) {
    const at = toTs(a.operation_time);
    if (at == null) continue;
    const diff = Math.abs(at - nt);
    if (diff <= WINDOW_MS && diff < bestDiff) { bestDiff = diff; best = a; }
  }
  if (best) {
    if (!seen.has(best.request_id)) {
      seen.add(best.request_id);
      statements.push(
        "UPDATE `ds_operation_audit_log` SET request_payload = JSON_SET(COALESCE(request_payload, JSON_OBJECT()), '$.ds_token', " +
        sqlQuote(n.token) + ") WHERE request_id = " + sqlQuote(best.request_id) +
        " AND (request_payload IS NULL OR JSON_UNQUOTE(JSON_EXTRACT(request_payload, '$.ds_token')) IS NULL OR JSON_UNQUOTE(JSON_EXTRACT(request_payload, '$.ds_token')) = '');"
      );
      matched++;
    }
  } else { unmatched++; }
}

const pgOffset = (pgItems[0] && pgItems[0].json && pgItems[0].json.offset) || 0;
if (statements.length === 0) {
  return [{ json: { ok: true, offset: pgOffset, statementCount: 0, matched: 0, unmatched: unmatched, n8nCount: pgItems.length, auditCount: auditRows.length, message: '本批没有需要回填的记录' } }];
}

const batches = [];
const batchCount = Math.ceil(statements.length / BATCH_SIZE);
for (let i = 0; i < statements.length; i += BATCH_SIZE) {
  const chunk = statements.slice(i, i + BATCH_SIZE);
  batches.push({
    json: {
      ok: true,
      offset: pgOffset,
      batchIndex: batches.length,
      batchCount: batchCount,
      statementCount: statements.length,
      matched: matched,
      unmatched: unmatched,
      n8nCount: pgItems.length,
      auditCount: auditRows.length,
      sql_b64: Buffer.from(chunk.join('\n'), 'utf8').toString('base64'),
    },
  });
}
return batches;

const items = $('分批写回Token').all();
let totalMatched = 0;
let totalStmts = 0;
let batchesDone = items.length;
for (const it of items) {
  const j = it.json || {};
  if (typeof j.matched === 'number') totalMatched += j.matched;
  if (typeof j.statementCount === 'number') totalStmts += j.statementCount;
}
return [{ json: { ok: true, batchesDone: batchesDone, totalMatched: totalMatched, totalStatements: totalStmts, message: '回填完成' } }];
